import{_ as t,c as e,o as i,a3 as r}from"./chunks/framework.CoV49S2T.js";const u=JSON.parse('{"title":"簡介","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/introduction.md","filePath":"zh-TW/guide/introduction.md","lastUpdated":1786595765000}'),o={name:"zh-TW/guide/introduction.md"};function l(n,a,s,h,d,c){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="簡介" tabindex="-1">簡介 <a class="header-anchor" href="#簡介" aria-label="Permalink to &quot;簡介&quot;">​</a></h1><h2 id="關於-clipboardxai" tabindex="-1">關於 ClipboardxAI <a class="header-anchor" href="#關於-clipboardxai" aria-label="Permalink to &quot;關於 ClipboardxAI&quot;">​</a></h2><p><strong>ClipboardxAI</strong> 是一款專為 macOS 打造的智慧剪貼簿管理工具。每當你複製文字、程式碼或連結時，都會被儲存到選單列中可搜尋的歷史紀錄裡。只要點一下——或是完全自動地——你就能對該筆剪貼內容執行動作：摘要、翻譯、整理，或是交由雲端 AI 模型處理。</p><p>它的設計圍繞兩類工具：</p><ul><li><strong>內建本地工具</strong>：完全在你的 Mac 上執行，不需要任何網路連線。</li><li><strong>AI 動作</strong>：呼叫你自行設定的雲端模型（使用你自己的 API key，儲存在系統 Keychain 中）。</li></ul><h2 id="主要功能" tabindex="-1">主要功能 <a class="header-anchor" href="#主要功能" aria-label="Permalink to &quot;主要功能&quot;">​</a></h2><h3 id="📋-剪貼簿歷史" tabindex="-1">📋 剪貼簿歷史 <a class="header-anchor" href="#📋-剪貼簿歷史" aria-label="Permalink to &quot;📋 剪貼簿歷史&quot;">​</a></h3><p>你複製的一切都會自動被擷取並保存在可搜尋的歷史紀錄中。從選單列隨時回到任何先前的剪貼內容——不再遺失任何片段。</p><h3 id="⚡-智慧建議" tabindex="-1">⚡ 智慧建議 <a class="header-anchor" href="#⚡-智慧建議" aria-label="Permalink to &quot;⚡ 智慧建議&quot;">​</a></h3><p>ClipboardxAI 會針對目前的剪貼內容建議最相關的動作。你可以接受建議，也可以瀏覽完整的工具清單。</p><h3 id="🛠️-內建本地工具" tabindex="-1">🛠️ 內建本地工具 <a class="header-anchor" href="#🛠️-內建本地工具" aria-label="Permalink to &quot;🛠️ 內建本地工具&quot;">​</a></h3><p>離線、私密、即時：</p><ul><li><strong>擷取連結（Extract Links）</strong> — 從一段文字中擷取出所有 URL。</li><li><strong>統計計數（Count Stats）</strong> — 字數、字元數、行數與句數統計。</li><li><strong>摺疊空白行（Collapse Blank Lines）</strong> — 一步整理貼上的文字。</li></ul><p>未來會陸續加入更多本地工具——它們永遠不會離開你的裝置。</p><h3 id="✨-ai-動作" tabindex="-1">✨ AI 動作 <a class="header-anchor" href="#✨-ai-動作" aria-label="Permalink to &quot;✨ AI 動作&quot;">​</a></h3><p>將目前的剪貼內容送到雲端模型以：</p><ul><li><strong>摘要</strong> 長篇文章與串文。</li><li><strong>翻譯</strong> 不同語言之間的內容。</li><li><strong>重寫 / 潤飾</strong> 語氣與清晰度。</li><li>執行來自 <strong>Marketplace</strong> 的任何動作。</li></ul><h3 id="🛒-動作市集-action-marketplace" tabindex="-1">🛒 動作市集（Action Marketplace） <a class="header-anchor" href="#🛒-動作市集-action-marketplace" aria-label="Permalink to &quot;🛒 動作市集（Action Marketplace）&quot;">​</a></h3><p>瀏覽社群製作的 AI 動作，並透過深層連結（<code>clipboardxai://install?action=&lt;id&gt;</code>）一鍵安裝。分類包含寫作、開發者、生產力、翻譯、社群與分析。</p><h3 id="🔒-以隱私為本" tabindex="-1">🔒 以隱私為本 <a class="header-anchor" href="#🔒-以隱私為本" aria-label="Permalink to &quot;🔒 以隱私為本&quot;">​</a></h3><p>你的剪貼簿歷史始終保留在你的裝置上。雲端 AI 是<strong>可選功能</strong>：啟用後，內容只會傳送給<em>你</em>選擇的供應商，並使用儲存在你 Keychain 中的 API key。我們絕不接收或儲存你的剪貼內容，也不會收集任何分析數據或遙測資訊。</p><h2 id="系統需求" tabindex="-1">系統需求 <a class="header-anchor" href="#系統需求" aria-label="Permalink to &quot;系統需求&quot;">​</a></h2><ul><li><strong>作業系統</strong>：macOS 14 Sonoma 或以上版本</li><li><strong>CPU</strong>：Apple Silicon（M 系列）或 Intel（64 位元）</li><li><strong>記憶體</strong>：最低 4 GB RAM，建議 8 GB</li><li><strong>儲存空間</strong>：安裝約需 ~50 MB</li><li><strong>使用雲端 AI</strong>：需要來自建方支援供應商的 API key（DeepSeek、MiniMax、Zhipu GLM、Kimi、Mistral、Ollama、OpenAI、Anthropic 或 Gemini）</li></ul><h2 id="支援語言" tabindex="-1">支援語言 <a class="header-anchor" href="#支援語言" aria-label="Permalink to &quot;支援語言&quot;">​</a></h2><p>本應用程式與本網站支援 English、简体中文、繁體中文、日本語、德文（German）、西班牙文（Spanish）與法文（French），共 7 種語言。</p><h2 id="開始使用" tabindex="-1">開始使用 <a class="header-anchor" href="#開始使用" aria-label="Permalink to &quot;開始使用&quot;">​</a></h2><p>如果你剛接觸 ClipboardxAI，請先從<a href="/zh-TW/guide/installation.html">安裝指南</a>開始，讓應用程式在你的 Mac 上順利執行，接著閱讀<a href="/zh-TW/guide/usage.html">使用方式</a>了解動作是如何運作的。</p>',27)])])}const g=t(o,[["render",l]]);export{u as __pageData,g as default};
